import pandas as pd

df = pd.read_csv('tecr_net_corrected_extracted/tecr_net_corrected/annual_risk_set.csv', low_memory=False)

# Let's inspect the 21,615 sequences generated by the notebook
seq_idx = pd.read_csv('tecr_net_corrected_extracted/tecr_net_corrected/sequence_index.csv')
print(f"Notebook sequence_index.csv rows: {len(seq_idx)}")
print(f"Years in sequence_index.csv: {seq_idx['year'].value_counts().sort_index()}")
print(f"Total sequences in sequence_index: {len(seq_idx)}")

# Notice 21,615 is the sum:
# 2014: 2577, 2015: 2420, 2016: 2275, 2017: 2177, 2018: 2007, 2019: 1877, 2020: 1827, 2021: 1718, 2022: 1618, 2023: 1573, 2024: 1546
# Sum of 2014 to 2024 = 21,615!
#
# Where does 22,957 come from?
# 22,957 - 21,615 = 1,342.
# Which feature year has 1,342 sequences or what is the 1,342 difference?
# Let's check 2025? Or year 2013 with some filter? Or what if feature year 2024 target 2025?
# Let's check what has 1,342:
print("\nChecking sequences by year:")
for y in range(2011, 2025):
    count_in_seq = (seq_idx['year'] == y).sum()
    print(f"Year {y}: in sequence_index={count_in_seq}")

